<script>document.addEventListener('DOMContentLoaded',()=>{const modal=document.querySelector('[data-payment-modal]'),form=modal.querySelector('[data-payment-form]'),total=modal.querySelector('[data-payment-total]'),received=modal.querySelector('[data-payment-received]'),change=modal.querySelector('[data-payment-change]'),method=modal.querySelector('[data-payment-method]'),cash=modal.querySelector('[data-cash-field]');const update=()=>{const amount=parseFloat(total.textContent)||0,paid=parseFloat(received.value)||0;change.textContent=Math.max(0,paid-amount).toFixed(2)};document.querySelectorAll('[data-open-payment]').forEach(button=>button.addEventListener('click',()=>{total.textContent=button.dataset.total;modal.querySelector('[data-payment-label]').textContent=button.dataset.label;form.action=`{{ url('/caja/atenciones') }}/${button.dataset.attention}/cobrar`;received.value='';method.value='efectivo';cash.hidden=false;received.required=true;update();modal.hidden=false;received.focus()}));[received,method].forEach(input=>input.addEventListener('input',update));method.addEventListener('change',()=>{cash.hidden=method.value!=='efectivo';received.required=method.value==='efectivo';if(method.value!=='efectivo')received.value='';update()});document.querySelector('[data-close-payment]').addEventListener('click',()=>modal.hidden=true);modal.addEventListener('click',event=>{if(event.target===modal)modal.hidden=true})});</script>
